import React, { useEffect, useRef, useState } from "react";
import '../../component/grid.css';
import styles from './banner.module.css';
import '../../component/style.css';

function Banner() {
    // Ảnh banner
    const banners = [
        'https://res.cloudinary.com/dz7086zgw/image/upload/v1745290551/banner_img1_qdgrrs.jpg',
        'https://res.cloudinary.com/dz7086zgw/image/upload/v1745290551/banner_img2_uz8whp.jpg',
        'https://res.cloudinary.com/dz7086zgw/image/upload/v1745290551/banner_img3_xji2ro.jpg',
        'https://res.cloudinary.com/dz7086zgw/image/upload/v1745290553/banner_img4_glj94j.jpg',
        'https://res.cloudinary.com/dz7086zgw/image/upload/v1745290554/banner_img5_vxa0j0.jpg'
    ];

    // Các ref
    const listImgRef = useRef(null);
    const imgsRef = useRef([]);
    const btnLeftRef = useRef(null);
    const btnRightRef = useRef(null);
    const dotsRef = useRef([]);
    const autoChangeIntervalRef = useRef(null);

    // Ảnh hiện tại
    const [current, setCurrent] = useState(0);

    // Cập nhật slider khi ảnh thay đổi
    useEffect(function () {
        var listImg = listImgRef.current;
        var imgs = imgsRef.current;
        var dots = dotsRef.current;

        if (!listImg || !imgs || !dots) return;

        function updateSlider() {
            var width = 0;
            if (imgs[0]) {
                width = imgs[0].offsetWidth;
            }

            listImg.style.transform = 'translateX(' + (-width * current) + 'px)';

            for (var i = 0; i < dots.length; i++) {
                dots[i].classList.remove(styles.active);
                if (i === current) {
                    dots[i].classList.add(styles.active);
                }
            }
        }

        updateSlider();
    }, [current]);

    // Thiết lập các sự kiện và chuyển ảnh tự động
    useEffect(function () {
        var listImg = listImgRef.current;
        var imgs = imgsRef.current;
        var dots = dotsRef.current;
        var btnLeft = btnLeftRef.current;
        var btnRight = btnRightRef.current;

        if (!listImg || !imgs || !dots) return;

        // Cập nhật vị trí slide và dot
        function updateSlider() {
            var width = 0;
            if (imgs[0]) {
                width = imgs[0].offsetWidth;
            }

            listImg.style.transform = 'translateX(' + (-width * current) + 'px)';

            for (var i = 0; i < dots.length; i++) {
                dots[i].classList.remove(styles.active);
                if (i === current) {
                    dots[i].classList.add(styles.active);
                }
            }
        }

        // Di chuyển sang phải
        function toRight() {
            if (current === imgs.length - 1) {
                setCurrent(0);
            } else {
                setCurrent(current + 1);
            }
        }

        // Di chuyển sang trái
        function toLeft() {
            if (current === 0) {
                setCurrent(imgs.length - 1);
            } else {
                setCurrent(current - 1);
            }
        }

        // Khi click dot
        function dotClick(index) {
            setCurrent(index);
        }

        updateSlider();

        // Tự động chuyển ảnh mỗi 4 giây
        autoChangeIntervalRef.current = setInterval(function () {
            toRight();
        }, 4000);

        // Sự kiện click nút phải
        function handleRightClick() {
            clearInterval(autoChangeIntervalRef.current);
            toRight();
            autoChangeIntervalRef.current = setInterval(function () {
                toRight();
            }, 4000);
        }

        // Sự kiện click nút trái
        function handleLeftClick() {
            clearInterval(autoChangeIntervalRef.current);
            toLeft();
            autoChangeIntervalRef.current = setInterval(function () {
                toRight();
            }, 4000);
        }

        if (btnRight) {
            btnRight.addEventListener('click', handleRightClick);
        }

        if (btnLeft) {
            btnLeft.addEventListener('click', handleLeftClick);
        }

        for (var i = 0; i < dots.length; i++) {
            (function (index) {
                var dot = dots[index];
                if (dot) {
                    dot.addEventListener('click', function () {
                        dotClick(index);
                    });
                }
            })(i);
        }

        return function () {
            clearInterval(autoChangeIntervalRef.current);

            if (btnRight) {
                btnRight.removeEventListener('click', handleRightClick);
            }

            if (btnLeft) {
                btnLeft.removeEventListener('click', handleLeftClick);
            }

            for (var i = 0; i < dots.length; i++) {
                var dot = dots[i];
                if (dot) {
                    // Không remove cụ thể được vì function click trong vòng lặp là ẩn danh
                    dot.replaceWith(dot.cloneNode(true)); // mẹo gỡ sự kiện
                }
            }
        };
    }, []);

    // JSX hiển thị
    return (
        <div className={styles.banner}>
            <div className={styles['slide-show']}>
                <div
                    id="img-banners"
                    className="displayflex"
                    ref={listImgRef}
                    style={{ transition: 'transform 0.9s ease-in-out' }}
                >
                    {banners.map(function (banner, index) {
                        return (
                            <img
                                key={index}
                                src={banner}
                                className={styles['img-banner']}
                                ref={function (el) {
                                    imgsRef.current[index] = el;
                                }}
                            />
                        );
                    })}
                </div>
            </div>

            <div className={styles['btns-banner']}>
                <div
                    className={styles['btn-banner'] + ' icon-white ' + styles['btn-left']}
                    ref={btnLeftRef}
                >
                    <i className="fas fa-chevron-left" />
                </div>
                <div
                    className={styles['btn-banner'] + ' icon-white ' + styles['btn-right']}
                    ref={btnRightRef}
                >
                    <i className="fas fa-chevron-right" />
                </div>
            </div>

            <div className={styles.dots}>
                {banners.map(function (_, index) {
                    return (
                        <div
                            key={index}
                            className={styles.dot}
                            ref={function (el) {
                                dotsRef.current[index] = el;
                            }}
                        />
                    );
                })}
            </div>
        </div>
    );
}

export default Banner;
